/* A WHOLE, SPLIT INTO NAMED SHARES.
 *
 * Three things separate this from the ring it replaced (owner, 23.08): the arcs
 * are cut apart by a real gap instead of touching, so two shares never melt
 * into one shape; a share can take a SLOT colour when the ring is about
 * unrelated things rather than about statuses; and the hole answers about
 * whatever the pointer is on, which is the question a legend cannot answer
 * without making the reader count.
 */
.donut-chart {
  /* Local to this component: the ring's three diameters and its weight. The
   * default has to hold a number in its hole, which is what sets the floor. */
  --donut-size: calc(var(--space-16) * 1.5);
  --donut-stroke: 5;

  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
  min-inline-size: 0;
}
.donut-chart[data-size="sm"] { --donut-size: var(--space-16); }
.donut-chart[data-size="sm"] .donut-chart-value { font-size: var(--font-sm); }
/* THE CAPTION SHRINKS WITH THE RING, and the gap under the number goes with it.
 * The value scaled at `sm` and the word under it did not, so on the small ring
 * "findings" ran into the stroke it is supposed to sit inside (owner,
 * 2026-08-29). The hole is a fixed share of the diameter, which only holds the
 * promise if what goes in it scales too. */
.donut-chart[data-size="sm"] .donut-chart-caption { font-size: calc(var(--font-xs) * 0.85); }
.donut-chart[data-size="sm"] .donut-chart-center { gap: var(--space-2xs); }
.donut-chart[data-size="lg"] .donut-chart-value { font-size: var(--font-xl); }
.donut-chart[data-size="lg"] { --donut-size: calc(var(--space-16) * 2.25); }

.donut-chart-ring {
  position: relative;
  /* The ring READS under the pointer, it does not navigate: crosshair is the
   * cursor for "point at the data", the same one the plots wear, and `pointer`
   * here would promise a click that never comes (owner, 23.08). */
  cursor: crosshair;
  flex: none;
  inline-size: var(--donut-size);
  block-size: var(--donut-size);
}
.donut-chart-ring svg { display: block; inline-size: 100%; block-size: 100%; transform: rotate(-90deg); }

.donut-chart-track { fill: none; stroke: var(--chart-track); stroke-width: var(--donut-stroke); }

.donut-chart-arc {
  fill: none;
  stroke-width: var(--donut-stroke);
  stroke: var(--chart-1);
  /* The ring assembles itself: every arc sweeps out of the top at once, which
   * is one gesture rather than five. */
  transform-origin: center;
  animation: donut-chart-sweep var(--duration-slow) var(--ease-out) both;
  transition: stroke-width var(--duration-fast) var(--ease-out), opacity var(--duration-fast) var(--ease-out);
}
@keyframes donut-chart-sweep {
  from { stroke-dashoffset: 0; opacity: 0; }
}

/* The share under the pointer thickens and the rest step back — the ring's
 * version of what the bar chart's columns do. */
.donut-chart:has(.donut-chart-arc[data-active]) .donut-chart-arc:not([data-active]) { opacity: 0.6; }
.donut-chart-arc[data-active] { stroke-width: calc(var(--donut-stroke) + 1.5); }

/* THE SLOTS, when the ring is about unrelated things (sites, categories). */
.donut-chart-arc[data-series="2"], .donut-chart-dot[data-series="2"] { stroke: var(--chart-2); background: var(--chart-2); }
.donut-chart-arc[data-series="3"], .donut-chart-dot[data-series="3"] { stroke: var(--chart-3); background: var(--chart-3); }
.donut-chart-arc[data-series="4"], .donut-chart-dot[data-series="4"] { stroke: var(--chart-4); background: var(--chart-4); }
.donut-chart-arc[data-series="5"], .donut-chart-dot[data-series="5"] { stroke: var(--chart-5); background: var(--chart-5); }
.donut-chart-arc[data-series="6"], .donut-chart-dot[data-series="6"] { stroke: var(--chart-6); background: var(--chart-6); }

/* THE TONES, when it is about how much of it is bad. */
.donut-chart-arc[data-tone="neutral"] { stroke: var(--muted-foreground); }
.donut-chart-arc[data-tone="primary"] { stroke: var(--primary); }
.donut-chart-arc[data-tone="success"] { stroke: var(--chart-success); }
.donut-chart-arc[data-tone="warning"] { stroke: var(--chart-warning); }
.donut-chart-arc[data-tone="danger"]  { stroke: var(--chart-danger); }

/* The hole is not decoration: it is where the number the ring is ABOUT goes.
 * A fixed share of the diameter, so the number can never overrun the stroke. */
.donut-chart-center {
  position: absolute;
  inset: 19%;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: var(--space-1);
  text-align: center;
  pointer-events: none;
}
.donut-chart-value {
  font-size: var(--font-md);
  font-weight: var(--font-weight-semibold);
  line-height: var(--leading-none);
  font-variant-numeric: tabular-nums;
}
.donut-chart-caption {
  font-size: var(--font-xs);
  color: var(--muted-foreground);
  /* The hole swaps between the total and the share being read, and the two
   * captions are different lengths: without a line reserved the ring's middle
   * jumped as the pointer moved. */
  min-block-size: 1em;
}

/* THE LEGEND DROPS UNDER THE RING RATHER THAN OUT OF THE CARD.
 *
 * At 390px the ring, the names, the values and the percentages do not fit on
 * one line: the legend ran 23px past the card edge (page audit, 23.08). Below
 * its own minimum it takes the next line, where it has the whole card. */
.donut-chart-legend {
  flex: 1 1 10rem;
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--font-sm);
  min-inline-size: 0;
}
.donut-chart-legend > li {
  /* The row is the arc's hit area, and a row IS something you point at. */
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  border-radius: var(--radius-sm);
}
/* The legend is the same control as the ring: pointing at a row reads its
 * share, because that row is easier to hit than a 5px arc. */
.donut-chart-legend > li[data-active] { color: var(--foreground); }
.donut-chart-legend-value {
  margin-inline-start: auto;
  display: flex;
  gap: var(--space-2);
  color: var(--muted-foreground);
  font-variant-numeric: tabular-nums;
}
.donut-chart-share { min-inline-size: 2.5rem; text-align: end; }

.donut-chart-dot {
  inline-size: var(--space-2);
  block-size: var(--space-2);
  border-radius: var(--radius-full);
  background: var(--chart-1);
  flex: none;
}
.donut-chart-dot[data-tone="neutral"] { background: var(--muted-foreground); }
.donut-chart-dot[data-tone="primary"] { background: var(--primary); }
.donut-chart-dot[data-tone="success"] { background: var(--chart-success); }
.donut-chart-dot[data-tone="warning"] { background: var(--chart-warning); }
.donut-chart-dot[data-tone="danger"]  { background: var(--chart-danger); }

import "./DonutChart.css";
import { type ReactNode, useState } from "react";
import { cn } from "../lib/cn";
import { formatValue } from "../lib/chart";

type Tone = "neutral" | "primary" | "success" | "warning" | "danger";
type Size = "sm" | "md" | "lg";

export type Segment = {
  /** What this share IS — it appears in the legend and in the accessible name. */
  label: string;
  value: number;
  /** The status this share carries, when the ring answers "how much of it is
   *  bad". Omit it and the segment takes its slot colour instead, which is what
   *  a ring of unrelated things (sites, categories) wants. Do not mix the two
   *  in one ring: a slot colour beside a status colour reads as a status. */
  tone?: Tone;
};

/* Monolithic because the chart and its legend are one figure: the segments
 * decide both, and the legend is the only place a sighted reader gets the
 * values. Splitting them is how a legend drifts out of step with the ring it
 * labels. */
type Props = {
  segments: Segment[];
  /** What sits in the hole: the total, or the share that matters. Under the
   *  pointer the hole shows the segment being read instead. */
  center?: ReactNode;
  /** A word under it — "open", "of 320". */
  caption?: ReactNode;
  /** `md` when the ring is the block and the split is being studied, `sm` beside a headline
   *  number where it says how that breaks down.
   */
  size?: Size;
  /** Off when the segments are already named beside the chart. */
  legend?: boolean;
  /** Shares as percentages beside the values. */
  percent?: boolean;
  /** What the whole ring measures. */
  label?: string;
  /** BCP-47 tag for the numbers. Omit to follow the browser. */
  locale?: string;
  className?: string;
};

const R = 16;
const C = 2 * Math.PI * R;
/* The gap between two arcs, in the same units as the circumference: a 2-unit
 * hole in the ring, so two segments never melt into one shape. Same 2px surface
 * gap the stacked bars use. */
const GAP = 1.2;

/** A whole split into named shares: how much of the total is open, at risk,
 *  done. Hovering a share reads it in the hole. Reach for <Progress shape="ring"> when
 *  there is ONE value on a scale — a ring with a single segment is that
 *  component wearing a legend. 
 *
 * Copy: the caption says what the whole ring adds up to, because a share is
 * meaningless without its total. Segment labels are the categories' own
 * names, not abbreviations.
 */
export function DonutChart({ segments, center, caption, size, legend = true, percent, label, locale, className }: Props) {
  const [at, setAt] = useState<number | null>(null);
  const total = segments.reduce((sum, s) => sum + s.value, 0);
  if (!total) return null;

  const format = (v: number) => formatValue(v, locale);
  const share = (v: number) => `${Math.round((v / total) * 100)}%`;

  /* Each arc starts where the ones before it ended, so the offset is a running
   * sum rather than a variable reassigned while rendering. The gap is taken off
   * the arc itself, never off the offset, or the shares stop adding up. */
  const arcs = segments.map((s, i) => ({
    ...s,
    dash: Math.max(0, (s.value / total) * C - GAP),
    offset: (segments.slice(0, i).reduce((sum, prev) => sum + prev.value, 0) / total) * C,
  }));

  /* The values a sighted reader gets from the legend, said once for everyone
   * else. Built outside the JSX: a template inside a template is unreadable. */
  const summary = segments.map((s) => `${s.label} ${format(s.value)}`).join(", ");
  const read = at != null ? segments[at] : null;

  return (
    <div className={cn("donut-chart", className)} data-size={size} onMouseLeave={() => setAt(null)}>
      <div
        className="donut-chart-ring"
        role={label ? "img" : "presentation"}
        aria-label={label ? `${label}: ${summary}` : undefined}
      >
        <svg viewBox="0 0 40 40" aria-hidden="true" focusable="false">
          <circle className="donut-chart-track" cx="20" cy="20" r={R} />
          {arcs.map((a, i) => (
            <circle
              key={a.label}
              className="donut-chart-arc"
              data-tone={a.tone}
              data-series={a.tone ? undefined : (i % 6) + 1}
              data-active={at === i ? "" : undefined}
              cx="20"
              cy="20"
              r={R}
              strokeDasharray={`${a.dash} ${C - a.dash}`}
              strokeDashoffset={-a.offset}
            />
          ))}
        </svg>
        <div className="donut-chart-center">
          {/* Under the pointer the hole answers about the share being read, and
              goes back to the total when the pointer leaves. */}
          <span className="donut-chart-value">{read ? format(read.value) : center}</span>
          <span className="donut-chart-caption">{read ? read.label : caption}</span>
        </div>
      </div>
      {legend && (
        <ul className="donut-chart-legend">
          {segments.map((s, i) => (
            <li key={s.label} data-active={at === i ? "" : undefined} onMouseEnter={() => setAt(i)}>
              <span
                className="donut-chart-dot"
                data-tone={s.tone}
                data-series={s.tone ? undefined : (i % 6) + 1}
                aria-hidden="true"
              />
              {s.label}
              <span className="donut-chart-legend-value">
                {format(s.value)}
                {percent && <span className="donut-chart-share">{share(s.value)}</span>}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
